pub fn supported(locale: &str) -> &'static str {
    match locale {
        "es" => "es",
        "fr" => "fr",
        "pt" => "pt",
        "ja" => "ja",
        "zh" => "zh",
        _ => "en",
    }
}

pub fn tr(locale: &str, key: &str) -> &'static str {
    let locale = supported(locale);
    let index = match locale {
        "es" => 1,
        "fr" => 2,
        "pt" => 3,
        "ja" => 4,
        "zh" => 5,
        _ => 0,
    };
    ROWS.iter()
        .find(|(name, _)| *name == key)
        .map(|(_, values)| values[index])
        .unwrap_or("")
}

