#[cfg(test)]
mod tests {
    use super::{supported, tr, ROWS};

    #[test]
    fn every_translation_row_has_six_nonempty_locales() {
        assert!(ROWS
            .iter()
            .all(|(_, values)| values.iter().all(|value| !value.is_empty())));
        for locale in ["en", "es", "fr", "pt", "ja", "zh"] {
            assert_eq!(supported(locale), locale);
            assert_ne!(tr(locale, "catalog_title"), "catalog_title");
        }
    }
}
